use nexus_engine::{RuntimeWasmError,RuntimeWasmModule,WasmHostRegistry,WasmValue};
fn s(m:&mut Vec<u8>,id:u8,p:&[u8]){m.extend([id,p.len() as u8]);m.extend(p)}
fn module()->Vec<u8>{let mut m=b"\0asm\x01\0\0\0".to_vec();s(&mut m,1,&[1,0x60,0,1,0x7f]);s(&mut m,2,&[1,3,b'e',b'n',b'v',7,b'c',b'o',b'u',b'n',b't',b'e',b'r',3,0x7f,1]);s(&mut m,3,&[1,0]);s(&mut m,7,&[1,4,b'm',b'a',b'i',b'n',0,0]);s(&mut m,10,&[1,11,0,0x23,0,0x41,1,0x6a,0x24,0,0x23,0,0x0b]);m}
#[test]fn imported_global_is_shared_between_instances(){let p=RuntimeWasmModule::parse(&module()).unwrap();let mut h=WasmHostRegistry::default();h.register_global("env","counter",WasmValue::I32(4),true).unwrap();let mut a=p.instantiate_with_host(&h).unwrap();let mut b=p.instantiate_with_host(&h).unwrap();assert_eq!(a.invoke("main",&[]).unwrap(),Some(WasmValue::I32(5)));assert_eq!(b.invoke("main",&[]).unwrap(),Some(WasmValue::I32(6)));}
#[test]fn missing_global_blocks_instantiation(){let p=RuntimeWasmModule::parse(&module()).unwrap();assert!(matches!(p.instantiate(),Err(RuntimeWasmError::HostImport(_))));}
#[test]fn global_type_mismatch_blocks_instantiation(){let p=RuntimeWasmModule::parse(&module()).unwrap();let mut h=WasmHostRegistry::default();h.register_global("env","counter",WasmValue::I64(4),true).unwrap();assert!(matches!(p.instantiate_with_host(&h),Err(RuntimeWasmError::HostImport(_))));}
#[test]fn immutable_host_global_cannot_satisfy_mutable_import(){let p=RuntimeWasmModule::parse(&module()).unwrap();let mut h=WasmHostRegistry::default();h.register_global("env","counter",WasmValue::I32(4),false).unwrap();assert!(matches!(p.instantiate_with_host(&h),Err(RuntimeWasmError::HostImport(_))));}
